'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { usePOS } from '@/modules/pos/context/POSContext';
import { useRouter } from 'next/navigation';
import {
    ArrowLeft,
    Check,
    Users,
    ChevronRight,
    Timer,
    ArrowRightLeft,
    Combine,
    X,
    Armchair,
    UtensilsCrossed,
    Search,
    ClipboardList,
    LayoutGrid
} from 'lucide-react';
import { POSTable } from '../types/pos';
import { mockPOSAreas } from '../mock/posData';
import '../styles/pos-rush.css';

export const TableSelectionPage: React.FC = () => {
    const { session, setTable, mergeTables, unmergeTable, tables } = usePOS();
    const router = useRouter();

    // UI State
    const [activeAreaId, setActiveAreaId] = useState<string>('AREA1');
    const [selectedTableId, setSelectedTableId] = useState<string | null>(null);
    const [mergeMode, setMergeMode] = useState(false);
    const [selectedForMerge, setSelectedForMerge] = useState<string[]>([]);
    const [previewTable, setPreviewTable] = useState<POSTable | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    const areas = mockPOSAreas;

    // Filter tables by Area AND Search Query
    const currentTables = useMemo(() =>
        tables.filter(t => {
            const matchesArea = t.areaId === activeAreaId;
            const matchesSearch = searchQuery
                ? (t.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                    t.customerName?.toLowerCase().includes(searchQuery.toLowerCase()))
                : true;
            return matchesArea && matchesSearch;
        }),
        [tables, activeAreaId, searchQuery]);

    const selectedTable = useMemo(() =>
        tables.find(t => t.id === selectedTableId),
        [tables, selectedTableId]);

    // Handle initial active table
    useEffect(() => {
        if (session?.activeTable) {
            setSelectedTableId(session.activeTable.id);
            setActiveAreaId(session.activeTable.areaId);
        }
    }, [session?.activeTable]);

    // Cleanup selection on unmount or area change
    useEffect(() => {
        setSelectedTableId(null);
        setPreviewTable(null);
        if (!mergeMode) setSelectedForMerge([]);
    }, [activeAreaId, mergeMode]);

    const handleConfirm = () => {
        if (selectedTable && selectedTable.status === 'FREE') {
            setTable(selectedTable);
            router.push('/pos/menu');
        } else {
            router.push('/pos/menu');
        }
    };

    const handleTableClick = (table: POSTable) => {
        if (mergeMode) {
            // Prevent cross-zone merges for simplicity
            if (selectedForMerge.length > 0) {
                const firstTable = tables.find(t => t.id === selectedForMerge[0]);
                if (firstTable && firstTable.areaId !== table.areaId) return;
            }

            if (!selectedForMerge.includes(table.id)) {
                setSelectedForMerge(prev => [...prev, table.id]);
            } else {
                setSelectedForMerge(prev => prev.filter(id => id !== table.id));
            }
            return;
        }

        if (table.status === 'OCCUPIED' || table.status === 'RESERVED') {
            setPreviewTable(table);
            setSelectedTableId(table.id);
            return;
        }

        // Toggle selection
        if (table.id === selectedTableId) {
            setSelectedTableId(null);
            setPreviewTable(null);
        } else {
            setSelectedTableId(table.id);
            setPreviewTable(null);
        }
    };

    const getTableColor = (status: string, isSelected: boolean) => {
        if (isSelected) return '#31A4A9'; // Selected teal
        switch (status) {
            case 'FREE': return '#009F4F'; // Green
            case 'OCCUPIED': return '#EF4444'; // Red
            case 'RESERVED': return '#F59E0B'; // Amber
            case 'CLEANING': return '#94A3B8'; // Slate
            default: return '#009F4F';
        }
    };

    // Calculate dynamic info for bottom bar
    const mergeSelectionCount = selectedForMerge.length;
    const mergeTotalSeats = useMemo(() => {
        return tables
            .filter(t => selectedForMerge.includes(t.id))
            .reduce((acc, curr) => acc + curr.seats, 0);
    }, [tables, selectedForMerge]);

    return (
        <div style={{
            height: '100vh',
            display: 'flex',
            flexDirection: 'column',
            background: '#F8FAFC',
            color: '#1E293B',
            overflow: 'hidden'
        }}>
            {/* TOP BAR / HEADER */}
            <div style={{
                background: '#FFFFFF',
                borderBottom: '1px solid #E2E8F0',
                display: 'flex',
                flexDirection: 'column',
                flexShrink: 0,
                zIndex: 50
            }}>
                {/* ROW 1: Logo/Back + Zone Buttons + Actions */}
                <div style={{
                    height: '70px',
                    padding: '0 24px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: '24px'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                        <button onClick={() => router.push('/pos/dashboard')} className="hover-scale" style={{
                            width: '40px', height: '40px', borderRadius: '10px', background: '#F1F5F9', border: '1px solid #E2E8F0', color: '#64748B', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer'
                        }}>
                            <ArrowLeft size={20} />
                        </button>
                        <div>
                            <h1 style={{ fontSize: '20px', fontWeight: 800, margin: 0, color: '#0F172A', display: 'flex', alignItems: 'center', gap: '8px' }}>
                                <UtensilsCrossed size={20} className="text-sky-500" /> Floor Map
                            </h1>
                        </div>
                    </div>

                    {/* HORIZONTAL ZONES */}
                    <div style={{
                        flex: 1,
                        display: 'flex',
                        alignItems: 'center',
                        gap: '8px',
                        overflowX: 'auto',
                        padding: '0 12px',
                        scrollbarWidth: 'none'
                    }}>
                        {areas.map(area => {
                            const isActive = activeAreaId === area.id;
                            return (
                                <button
                                    key={area.id}
                                    onClick={() => setActiveAreaId(area.id)}
                                    style={{
                                        whiteSpace: 'nowrap',
                                        padding: '10px 20px',
                                        borderRadius: '12px',
                                        border: 'none',
                                        background: isActive ? '#0284C7' : '#F1F5F9',
                                        color: isActive ? 'white' : '#64748B',
                                        fontSize: '14px',
                                        fontWeight: isActive ? 700 : 600,
                                        cursor: 'pointer',
                                        transition: 'all 0.2s',
                                        boxShadow: isActive ? '0 4px 6px -1px rgba(2, 132, 199, 0.3)' : 'none',
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: '8px'
                                    }}
                                >
                                    {isActive && <LayoutGrid size={16} />}
                                    {area.name.replace('Outdoor Terrace', 'Outdoor')}
                                </button>
                            );
                        })}
                    </div>

                    {/* TOP ACTIONS: View Orders */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <button
                            onClick={() => router.push('/pos/orders')}
                            style={{
                                height: '44px',
                                padding: '0 20px',
                                borderRadius: '10px',
                                background: '#334155',
                                color: 'white',
                                border: 'none',
                                fontWeight: 700,
                                fontSize: '14px',
                                cursor: 'pointer',
                                display: 'flex',
                                alignItems: 'center',
                                gap: '8px'
                            }}
                        >
                            <ClipboardList size={18} />
                            View Orders
                        </button>
                    </div>
                </div>

                {/* ROW 2: Full Width Search */}
                <div style={{
                    padding: '12px 24px',
                    borderTop: '1px solid #F1F5F9',
                    background: '#FFFFFF'
                }}>
                    <div style={{ position: 'relative', width: '100%' }}>
                        <Search size={20} style={{ position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)', color: '#94A3B8' }} />
                        <input
                            type="text"
                            placeholder="Search tables or customers..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            style={{
                                width: '100%',
                                height: '50px',
                                paddingLeft: '48px',
                                paddingRight: '16px',
                                borderRadius: '12px',
                                border: '1px solid #E2E8F0',
                                background: '#F8FAFC',
                                fontSize: '16px',
                                fontWeight: 500,
                                outline: 'none',
                                color: '#1E293B'
                            }}
                        />
                    </div>
                </div>
            </div>

            {/* MAIN CONTENT AREA */}
            <div style={{ flex: 1, display: 'flex', overflow: 'hidden', padding: '24px', background: '#F1F5F9', position: 'relative' }}>

                {/* FLOOR MAP CANVAS */}
                <div style={{
                    flex: 1,
                    position: 'relative',
                    width: '100%',
                    height: '100%',
                    background: 'white',
                    borderRadius: '16px',
                    boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06)',
                    border: '1px solid #E2E8F0',
                    overflow: 'hidden' // Important for relative positioning
                }}>
                    <div style={{
                        width: '100%',
                        height: '100%',
                        overflow: 'auto',
                        padding: '40px',
                        position: 'relative'
                    }}>
                        {currentTables.length === 0 ? (
                            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%', color: '#94A3B8' }}>
                                <div style={{ background: '#F8FAFC', padding: '24px', borderRadius: '50%', marginBottom: '16px' }}>
                                    <Users size={48} />
                                </div>
                                <p style={{ fontWeight: 700, fontSize: '18px', color: '#475569' }}>No tables found</p>
                                <p style={{ fontSize: '14px' }}>Try adjusting your search or zone.</p>
                            </div>
                        ) : (
                            currentTables.map(table => {
                                const isSelected = selectedTableId === table.id || selectedForMerge.includes(table.id);

                                // Handle both % and px units for tiles
                                const isPercent = (table.width || 0) < 50;
                                const widthVal = isPercent ? `${table.width}%` : `${table.width || 90}px`;
                                const heightVal = isPercent ? `${table.height}%` : `${table.height || 90}px`;

                                // Tile Styling
                                const baseFontSize = isPercent ? 1.2 : 15;
                                const fontSize = isPercent ? `${baseFontSize}vw` : `${baseFontSize}px`;
                                // Adjust subsize relative to font size

                                return (
                                    <div
                                        key={table.id}
                                        onClick={() => handleTableClick(table)}
                                        onDoubleClick={() => {
                                            if (table.status === 'FREE') {
                                                setTable(table);
                                                router.push('/pos/menu');
                                            }
                                        }}
                                        style={{
                                            position: 'absolute',
                                            left: `${table.x}%`,
                                            top: `${table.y}%`,
                                            width: widthVal,
                                            height: heightVal,
                                            borderRadius: table.shape === 'circle' ? '50%' : '12px',
                                            background: getTableColor(table.status, isSelected),
                                            display: 'flex',
                                            flexDirection: 'column',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            cursor: 'pointer',
                                            transition: 'all 0.15s cubic-bezier(0.4, 0, 0.2, 1)',
                                            boxShadow: isSelected
                                                ? '0 0 0 4px #FFFFFF, 0 0 0 7px #31A4A9, 0 10px 15px -3px rgba(0,0,0,0.2)'
                                                : '0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1), inset 0 1px 0 rgba(255,255,255,0.2)',
                                            zIndex: isSelected ? 50 : 10,
                                            textAlign: 'center',
                                            color: '#FFFFFF',
                                            padding: '4px',
                                            transform: isSelected ? 'scale(1.05) translateY(-4px)' : 'scale(1)',
                                            border: '1px solid rgba(0,0,0,0.05)'
                                        }}
                                        className="active-pop"
                                    >
                                        <span style={{
                                            fontSize: fontSize,
                                            fontWeight: 800,
                                            lineHeight: 1.1,
                                            whiteSpace: 'nowrap',
                                            overflow: 'hidden',
                                            textOverflow: 'ellipsis',
                                            maxWidth: '100%',
                                            padding: '0 4px'
                                        }}>
                                            {table.name}
                                        </span>
                                        <span style={{
                                            fontSize: isPercent ? '0.9vw' : '11px',
                                            fontWeight: 600,
                                            marginTop: '2px',
                                            opacity: 0.9,
                                            background: 'rgba(0,0,0,0.1)',
                                            padding: '0 6px',
                                            borderRadius: '10px'
                                        }}>
                                            {table.durationMinutes ? `${table.durationMinutes}m` : `${table.seats}P`}
                                        </span>

                                        {/* Status Badge Overlays */}
                                        {table.status === 'OCCUPIED' && !isSelected && (
                                            <div style={{
                                                position: 'absolute',
                                                top: '-6px',
                                                right: '-6px',
                                                background: '#FFFFFF',
                                                color: '#EF4444',
                                                borderRadius: '50%',
                                                width: '24px',
                                                height: '24px',
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                fontSize: '11px',
                                                fontWeight: 800,
                                                boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
                                                border: '2px solid #FECACA',
                                                zIndex: 30
                                            }}>
                                                !
                                            </div>
                                        )}

                                        {/* Selection Checkmark */}
                                        {isSelected && mergeMode && (
                                            <div style={{
                                                position: 'absolute',
                                                top: '50%',
                                                left: '50%',
                                                transform: 'translate(-50%, -50%)',
                                                background: 'rgba(255,255,255,0.3)',
                                                borderRadius: '50%',
                                                padding: '4px'
                                            }}>
                                                <Check size={28} color="white" strokeWidth={4} />
                                            </div>
                                        )}
                                    </div>
                                );
                            })
                        )}
                    </div>
                </div>

                {/* VISUAL & FLOATING ELEMENTS: Legend */}
                <div style={{
                    position: 'absolute',
                    top: '40px',
                    right: '40px',
                    background: 'rgba(255, 255, 255, 0.95)',
                    padding: '8px 12px',
                    borderRadius: '10px',
                    boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                    backdropFilter: 'blur(8px)',
                    zIndex: 20,
                    display: 'flex',
                    gap: '12px',
                    border: '1px solid #E2E8F0'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <div style={{ width: '10px', height: '10px', borderRadius: '3px', background: '#009F4F' }} />
                        <span style={{ fontSize: '11px', fontWeight: 700, color: '#475569' }}>Free</span>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <div style={{ width: '10px', height: '10px', borderRadius: '3px', background: '#EF4444' }} />
                        <span style={{ fontSize: '11px', fontWeight: 700, color: '#475569' }}>Occupied</span>
                    </div>
                </div>

                {/* PREVIEW PANEL - Right Sidebar Overlay / Slide-over */}
                {previewTable && (
                    <div style={{
                        position: 'absolute',
                        right: '24px',
                        top: '24px',
                        bottom: '24px',
                        width: '320px',
                        background: '#FFFFFF',
                        borderRadius: '16px',
                        boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1), 0 0 0 1px rgba(0,0,0,0.05)',
                        display: 'flex',
                        flexDirection: 'column',
                        zIndex: 60,
                        overflow: 'hidden'
                    }}>
                        <div style={{ padding: '20px', background: '#F8FAFC', borderBottom: '1px solid #E2E8F0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <h2 style={{ fontSize: '18px', fontWeight: 800, color: '#0F172A', margin: 0 }}>Table Details</h2>
                            <button onClick={() => setPreviewTable(null)} style={{ background: '#E2E8F0', border: 'none', color: '#64748B', borderRadius: '8px', width: '30px', height: '30px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
                                <X size={16} />
                            </button>
                        </div>

                        <div style={{ padding: '24px', overflowY: 'auto', flex: 1 }}>
                            <div style={{ textAlign: 'center', marginBottom: '24px' }}>
                                <div style={{
                                    width: '80px', height: '80px', borderRadius: '24px',
                                    background: '#FEF2F2', color: '#EF4444',
                                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    fontSize: '28px', fontWeight: 800, margin: '0 auto 12px'
                                }}>
                                    {previewTable.name.replace(/[^0-9]/g, '')}
                                </div>
                                <h3 style={{ fontSize: '24px', fontWeight: 800, margin: 0, color: '#0F172A' }}>{previewTable.name}</h3>
                                <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', marginTop: '8px', padding: '4px 12px', background: '#FEE2E2', borderRadius: '20px' }}>
                                    <div style={{ width: '6px', height: '6px', borderRadius: '50%', background: '#EF4444' }} />
                                    <span style={{ color: '#EF4444', fontWeight: 700, fontSize: '12px' }}>OCCUPIED</span>
                                </div>
                            </div>

                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '24px' }}>
                                <div style={{ background: '#F8FAFC', padding: '16px', borderRadius: '12px', border: '1px solid #E2E8F0', textAlign: 'center' }}>
                                    <Timer size={20} className="text-slate-400 mx-auto mb-2" />
                                    <p style={{ fontSize: '10px', color: '#64748B', fontWeight: 700, textTransform: 'uppercase', margin: 0 }}>Time</p>
                                    <span style={{ fontSize: '18px', fontWeight: 800, color: '#0F172A' }}>{previewTable.durationMinutes || 0}m</span>
                                </div>
                                <div style={{ background: '#F8FAFC', padding: '16px', borderRadius: '12px', border: '1px solid #E2E8F0', textAlign: 'center' }}>
                                    <Users size={20} className="text-slate-400 mx-auto mb-2" />
                                    <p style={{ fontSize: '10px', color: '#64748B', fontWeight: 700, textTransform: 'uppercase', margin: 0 }}>Guests</p>
                                    <span style={{ fontSize: '18px', fontWeight: 800, color: '#0F172A' }}>{previewTable.seats}</span>
                                </div>
                            </div>
                        </div>

                        <div style={{ padding: '20px', borderTop: '1px solid #F1F5F9', background: '#FFFFFF' }}>
                            <button
                                onClick={() => router.push('/pos/menu')}
                                style={{
                                    height: '50px',
                                    width: '100%',
                                    borderRadius: '12px',
                                    background: '#0284C7',
                                    border: 'none',
                                    color: 'white',
                                    fontSize: '15px',
                                    fontWeight: 700,
                                    cursor: 'pointer',
                                    boxShadow: '0 4px 6px -1px rgba(2, 132, 199, 0.2)'
                                }}
                            >
                                View Active Order
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* BOTTOM BAR - Actions Context */}
            <div style={{
                height: '80px',
                background: '#FFFFFF',
                borderTop: '1px solid #E2E8F0',
                display: 'flex',
                alignItems: 'center',
                padding: '0 32px',
                justifyContent: 'space-between',
                flexShrink: 0,
                zIndex: 50
            }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                    {/* Info for Bottom Bar */}
                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        <span style={{ fontSize: '11px', color: '#64748B', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.5px' }}>Status</span>
                        {mergeMode ? (
                            <span style={{ fontSize: '18px', fontWeight: 800, color: '#31A4A9' }}>
                                Merging {mergeSelectionCount} Tables
                            </span>
                        ) : (
                            <span style={{ fontSize: '18px', fontWeight: 800, color: selectedTable ? '#0F172A' : '#94A3B8' }}>
                                {selectedTable ? `Selected: ${selectedTable.name}` : 'Select a table to start'}
                            </span>
                        )}
                    </div>
                </div>

                <div style={{ display: 'flex', gap: '16px' }}>
                    <button
                        onClick={() => {
                            setMergeMode(!mergeMode);
                            setSelectedForMerge([]);
                            setSelectedTableId(null);
                        }}
                        style={{
                            height: '52px',
                            padding: '0 24px',
                            borderRadius: '10px',
                            background: mergeMode ? '#FEF2F2' : '#FFFFFF',
                            border: mergeMode ? '1px solid #FECACA' : '1px solid #E2E8F0',
                            color: mergeMode ? '#EF4444' : '#64748B',
                            fontWeight: 700,
                            cursor: 'pointer',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '10px'
                        }}
                    >
                        {mergeMode ? <X size={18} /> : <Combine size={18} />}
                        {mergeMode ? 'Cancel' : 'Merge'}
                    </button>

                    <button
                        onClick={handleConfirm}
                        disabled={!selectedTableId || selectedTable?.status !== 'FREE'}
                        style={{
                            height: '52px',
                            padding: '0 32px',
                            borderRadius: '10px',
                            background: selectedTableId && selectedTable?.status === 'FREE' ? '#0ea5e9' : '#E2E8F0',
                            color: 'white',
                            border: 'none',
                            fontSize: '16px',
                            fontWeight: 700,
                            cursor: selectedTableId && selectedTable?.status === 'FREE' ? 'pointer' : 'not-allowed',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '12px',
                            opacity: selectedTableId && selectedTable?.status === 'FREE' ? 1 : 0.7
                        }}
                    >
                        Start Order <ChevronRight size={20} />
                    </button>
                </div>
            </div>

            <style jsx>{`
                .active-pop:active {
                    transform: scale(0.96);
                }
                .hover-scale:hover {
                    transform: scale(1.05);
                }
                div::-webkit-scrollbar {
                    width: 0px;
                    height: 0px;
                }
            `}</style>
        </div>
    );
};
